import{_ as e,o as d,c as o,a3 as r}from"./chunks/framework.CWSmAuPU.js";const u=JSON.parse('{"title":"命令","description":"","frontmatter":{},"headers":[],"relativePath":"reference/commands.md","filePath":"reference/commands.md","lastUpdated":1792212140000}'),c={name:"reference/commands.md"};function a(s,t,l,i,n,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="命令" tabindex="-1">命令 <a class="header-anchor" href="#命令" aria-label="Permalink to &quot;命令&quot;">​</a></h1><p>req-kit 有三类入口：在 Paseo 对话中使用的 <strong>skill</strong>，终端中的 <strong><code>req</code> 命令</strong>，以及 skill 在背后调用的<strong>流水线启动器</strong>。日常使用只需要第一类。</p><h2 id="对话中的-skill" tabindex="-1">对话中的 skill <a class="header-anchor" href="#对话中的-skill" aria-label="Permalink to &quot;对话中的 skill&quot;">​</a></h2><table tabindex="0"><thead><tr><th>输入</th><th>作用</th><th>通常谁用</th></tr></thead><tbody><tr><td><code>/req &lt;一句话&gt;</code></td><td>需求开发入口：新需求、小改动、查看进度、暂停或继续、修改需求、开始测试验证、验收、上线后问题、接手。由它判断走哪本手册</td><td>使用者</td></tr><tr><td><code>/req-setup</code></td><td>项目接入：生成项目说明、验证方法、<code>paseo.json</code>，确认后提交</td><td>开发或熟悉项目的测试同事</td></tr><tr><td><code>/req-doctor</code></td><td>体检：安装、配置、daemon、当前项目</td><td>任何人</td></tr><tr><td><code>/req-retro</code></td><td>复盘：需求做完后回顾返工、中断和变更，把改进落到 CI、配置、项目说明或提示词</td><td>开发同事</td></tr></tbody></table><p>Pi 中写作 <code>/skill:req</code>。同一个对话里，之后的&quot;做到哪了&quot;&quot;先停一下&quot;&quot;继续开发&quot;&quot;开始测试验证&quot;&quot;我要验收&quot;不需要再带 <code>/req</code>。</p><h2 id="req-命令" tabindex="-1">req 命令 <a class="header-anchor" href="#req-命令" aria-label="Permalink to &quot;req 命令&quot;">​</a></h2><p>安装后提供 <code>req</code>（同名命令 <code>req-kit</code>，避免和其他工具冲突）。Windows PowerShell 受执行策略限制时用 <code>req.cmd</code>。</p><h3 id="在项目目录中" tabindex="-1">在项目目录中 <a class="header-anchor" href="#在项目目录中" aria-label="Permalink to &quot;在项目目录中&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>req list</code></td><td>列出这个项目所有工作区中的需求和阶段</td></tr><tr><td><code>req status [需求]</code></td><td>查看进度；只有一个需求运行过时可以不写</td></tr><tr><td><code>req stop &lt;需求&gt;</code></td><td>停止流水线（之后可以继续）；同时取消预约的开始、提醒、自动继续</td></tr><tr><td><code>req resume &lt;需求&gt;</code></td><td>从上次中断处继续；需求改过时只处理变化的部分</td></tr><tr><td><code>req approve &lt;需求&gt;</code></td><td>需求方看过 <code>preview.md</code> 并确认后，从方案确认点继续开发</td></tr><tr><td><code>req verify &lt;需求&gt; [--verify-env local|deployed] [--defects fix|handback|report]</code></td><td>研发完成后开始测试验证（分阶段执行时）</td></tr><tr><td><code>req start &lt;需求&gt; [--profile quick|standard] [--phases gated] [--at 22:00]</code></td><td>启动流水线（通常由 <code>/req</code> 在对话中启动）</td></tr><tr><td><code>req digest [--notify]</code></td><td>项目的需求总览；<code>--notify</code> 同时发到外部通知</td></tr><tr><td><code>req digest --schedule &quot;0 9 * * 1&quot;</code></td><td>让 Paseo 按时间表发送需求总览；取消：<code>req digest --cancel &lt;ID&gt;</code></td></tr><tr><td><code>req sync &lt;需求&gt;</code></td><td>把需求同步到对接的外部系统：补发没有成功的调用、补建卡片、更新状态</td></tr><tr><td><code>req integration test [需求]</code></td><td>显示对接外部系统时每个事件会执行的命令，不真正调用</td></tr><tr><td><code>req start --from &lt;系统&gt;:&lt;卡号&gt; [--repo &lt;仓库&gt;]</code></td><td>从需求管理系统中的一张卡片开始需求：建功能目录和需求会话，问题和确认通过卡片描述；不写 <code>--repo</code> 时按子系统选仓库</td></tr><tr><td><code>req card check [&lt;卡号&gt; | --all]</code></td><td>读取需求方在卡片中的回复，把新内容转给需求会话</td></tr><tr><td><code>req card publish &lt;卡号&gt;</code></td><td>需求会话使用：把 <code>card-ai.md</code> 写进卡片的 AI 区</td></tr><tr><td><code>req card list</code></td><td>本机从卡片开始的需求和各自的进展</td></tr><tr><td><code>req card route [--add &lt;仓库&gt; | --remove &lt;仓库&gt;]</code></td><td>本机接收卡片的仓库和各自的子系统；<code>req start --from</code> 不写 <code>--repo</code> 时按它选仓库</td></tr><tr><td><code>req factory once | run | start | stop | status | service</code></td><td>接单器：定时为标题带 <code>[AI]</code> 的新卡片开始需求、转达需求方的回复；<code>once</code> 检查一次，<code>start</code>/<code>stop</code> 后台运行，<code>service</code> 给出作为系统服务运行的写法</td></tr><tr><td><code>req index --rebuild [目录…]</code></td><td>把这些仓库中运行过的需求登记进本机的需求索引（1.9 之前运行过的需求用）</td></tr></tbody></table><h3 id="使用统计-任何目录" tabindex="-1">使用统计（任何目录） <a class="header-anchor" href="#使用统计-任何目录" aria-label="Permalink to &quot;使用统计（任何目录）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>req stats [--since 30d] [--month 2026-10]</code></td><td>本机的使用统计：需求数、交付周期、返工、等待、各步骤用时、用量；<code>--json</code>、<code>--csv</code></td></tr><tr><td><code>req stats --report [--out 目录]</code></td><td>生成汇报用的 <code>.md</code> 汇总和 <code>.csv</code> 明细</td></tr><tr><td><code>req stats --export [文件]</code></td><td>导出本机的运行记录</td></tr><tr><td><code>req stats --merge &lt;文件…&gt; --report</code></td><td>汇总几台机器的导出</td></tr><tr><td><code>req index [--prune]</code></td><td>本机记录的需求；<code>--prune</code> 移除目录已不在的</td></tr><tr><td><code>req api &lt;命令&gt; …</code></td><td>给程序用的 JSON 输出，见 <a href="./contracts/cli-json">req api</a></td></tr></tbody></table><h3 id="paseo-插件" tabindex="-1">Paseo 插件 <a class="header-anchor" href="#paseo-插件" aria-label="Permalink to &quot;Paseo 插件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>req plugin install [--yes]</code></td><td>安装或更新 req-kit 的 Paseo 插件；需要时询问是否打开 Paseo 的插件总开关</td></tr><tr><td><code>req plugin status</code></td><td>插件是否在运行</td></tr><tr><td><code>req plugin remove</code></td><td>从 Paseo 移除插件</td></tr></tbody></table><p><code>&lt;需求&gt;</code> 可以写功能目录（<code>docs/features/20261012-sms-login</code>）、目录名，或名称中能唯一确定的一部分（<code>sms-login</code>）。</p><h3 id="本机维护" tabindex="-1">本机维护 <a class="header-anchor" href="#本机维护" aria-label="Permalink to &quot;本机维护&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>req doctor [--no-project]</code></td><td>体检：安装、配置、daemon、当前项目</td></tr><tr><td><code>req configure</code></td><td>配置向导：为 builder、reviewer 和备用模型选择 agent</td></tr><tr><td><code>req configure --auto</code></td><td>不提问，按推荐选好（1.12；安装时自动运行）</td></tr><tr><td><code>req reply &lt;需求&gt; &lt;回复&gt;</code></td><td>把回答或方案意见转给需求的对话（1.12；插件&quot;等你处理&quot;用它）</td></tr><tr><td><code>req setup</code></td><td>启用 npm 安装的这个版本、安装 skill（安装脚本会自动运行）</td></tr><tr><td><code>req upgrade [版本] [--beta]</code></td><td>升级到最新版本（或指定版本），自动选能支持本机 Paseo 的版本；<code>--check</code> 只看有没有新版本</td></tr><tr><td><code>req versions</code></td><td>已安装的版本和可用的版本</td></tr><tr><td><code>req use &lt;版本&gt;</code></td><td>切换到已安装的另一个版本（回滚）</td></tr><tr><td><code>req check</code></td><td>检查安装状态</td></tr><tr><td><code>req notify-test [--type …]</code></td><td>给配置的外部通知（如企业 IM）发一条测试消息</td></tr><tr><td><code>req version</code></td><td>显示版本和安装位置</td></tr></tbody></table><h2 id="流水线启动器" tabindex="-1">流水线启动器 <a class="header-anchor" href="#流水线启动器" aria-label="Permalink to &quot;流水线启动器&quot;">​</a></h2><p><code>/req</code> 在对话中执行的是 <code>node &lt;安装目录&gt;/bin/start-pipeline.mjs</code>，在 bash、PowerShell、cmd 中写法相同。在 Paseo 对话中运行时，它自动识别当前对话（<code>PASEO_AGENT_ID</code>）和工作目录（<code>PASEO_AGENT_CWD</code>）。</p><table tabindex="0"><thead><tr><th>选项</th><th>作用</th></tr></thead><tbody><tr><td><code>--feature &lt;功能目录&gt;</code></td><td>要操作的需求；可以只写名称的一部分</td></tr><tr><td><code>--status</code> / <code>--stop</code> / <code>--list</code></td><td>查看进度 / 停止 / 列出需求</td></tr><tr><td><code>--resume</code> / <code>--restart</code></td><td>从中断处继续 / 丢弃结果从零开始</td></tr><tr><td><code>--profile quick|standard</code></td><td>档位；不传时读需求说明中的&quot;档位&quot;，再用配置的 <code>defaultProfile</code></td></tr><tr><td><code>--phases continuous|gated|develop-only</code></td><td>执行方式；不传时读需求说明中的&quot;执行方式&quot;，再用配置的 <code>phases.mode</code></td></tr><tr><td><code>--approve</code></td><td>方案确认点：需求方确认了方案，继续开发（等待确认时单独的 <code>--resume</code> 会被拒绝；要修改就先更新需求说明再 <code>--resume</code>）</td></tr><tr><td><code>--phase verify</code></td><td>开始（或继续）测试验证阶段；研发完成、待测试时单独的 <code>--resume</code> 效果相同</td></tr><tr><td><code>--verify-env local|deployed</code>、<code>--defects fix|handback|report</code></td><td>开始测试验证时临时指定环境和缺陷处理方式</td></tr><tr><td><code>--verify-at &lt;时间&gt;</code></td><td>分阶段时，研发完成后在这个时间自动开始测试验证</td></tr><tr><td><code>--at &lt;时间&gt;</code></td><td>预约开始：<code>22:00</code>、<code>明天 8:30</code>、<code>2026-10-14 08:30</code>、<code>+2h</code></td></tr><tr><td><code>--worktree</code></td><td>为这个需求新建 Paseo worktree 工作区并在那里开发（对话目录不变）</td></tr><tr><td><code>--spec-review</code></td><td>确认前请另一个模型独立审阅需求说明草稿</td></tr><tr><td><code>--repo</code>、<code>--origin-agent</code>、<code>--config</code></td><td>仓库目录、发起对话、配置文件（通常不需要写）</td></tr></tbody></table><h2 id="安装脚本" tabindex="-1">安装脚本 <a class="header-anchor" href="#安装脚本" aria-label="Permalink to &quot;安装脚本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>系统</th><th>命令</th></tr></thead><tbody><tr><td>macOS、Linux、Git Bash、WSL</td><td><code>curl -fsSL https://paseo-req-kit.vercel.app/install.sh | sh</code></td></tr><tr><td>Windows PowerShell</td><td><code>irm https://paseo-req-kit.vercel.app/install.ps1 | iex</code></td></tr></tbody></table><p><code>install.sh</code> 的选项写在 <code>sh -s --</code> 之后：<code>--beta</code>、<code>--version &lt;版本&gt;</code>、<code>--from npm|release</code>、<code>--no-configure</code>、<code>--skip-paseo</code>（不检查、不安装 Paseo）、<code>--with-plugin</code>（直接安装 Paseo 插件）、<code>--no-plugin</code>。<code>install.ps1</code> 的选项用变量：<code>$ReqKitBeta = $true</code>、<code>$ReqKitVersion = &quot;1.9.1&quot;</code>、<code>$ReqKitFrom = &quot;release&quot;</code>、<code>$ReqKitNoConfigure = $true</code>、<code>$ReqKitSkipPaseo = $true</code>、<code>$ReqKitPlugin = &quot;yes&quot;</code>（或 <code>&quot;no&quot;</code>）。没有 Paseo 时脚本会安装 Paseo 命令行、开启它的网页界面并启动 daemon。</p>',22)])])}const p=e(c,[["render",a]]);export{u as __pageData,p as default};
